"""Mutation fuzzer: compare planner verdicts against refvalid verdicts."""
import copy, json, random, subprocess, sys
sys.path.insert(0, "/app/work")
import gen, gen2, refvalid

PLANNER = "/app/submission/planner.py"


def mutations(rng, obj):
    """Yield (label, mutated-object-or-text) pairs, mostly invalid."""
    out = []
    def M(label, fn):
        c = copy.deepcopy(obj)
        try:
            r = fn(c)
        except Exception:
            return
        out.append((label, r if isinstance(r, str) else json.dumps(r)))

    M("drop key", lambda c: c.pop(rng.choice(list(c.keys()))) or c)
    M("extra key", lambda c: c.update(zzz=1))
    def dupkey(c):
        return json.dumps(c)[:-1] + ', "epoch": ' + str(c["epoch"]) + "}"
    M("dup key", dupkey)
    M("epoch float", lambda c: c.update(epoch=float(c["epoch"])))
    M("epoch bool", lambda c: c.update(epoch=True))
    M("epoch str", lambda c: c.update(epoch=str(c["epoch"])))
    M("epoch neg", lambda c: c.update(epoch=-1))
    M("epoch big", lambda c: c.update(epoch=2147483648))
    M("nc 0", lambda c: c.update(node_count=0))
    M("nc 97", lambda c: c.update(node_count=97))
    M("budget neg", lambda c: c.update(budget=-1))
    M("budget big", lambda c: c.update(budget=98305))
    M("budget float", lambda c: c.update(budget=1.5))
    M("budget null", lambda c: c.update(budget=None))
    M("failed oor", lambda c: c.update(failed_edges=(c["failed_edges"] + [len(c["edges"])])))
    M("failed dup", lambda c: c.update(failed_edges=(c["failed_edges"] + c["failed_edges"][:1] + [0])) )
    M("failed notlist", lambda c: c.update(failed_edges=0))
    M("edges notlist", lambda c: c.update(edges={}))
    def edge_key(c):
        if c["edges"]:
            c["edges"][0]["extra"] = 1
        return c
    M("edge extra key", edge_key)
    def edge_drop(c):
        if c["edges"]:
            c["edges"][0].pop("capacity")
        return c
    M("edge drop key", edge_drop)
    def edge_cap0(c):
        if c["edges"]:
            c["edges"][0]["capacity"] = 0
        return c
    M("edge cap 0", edge_cap0)
    def edge_cap_big(c):
        if c["edges"]:
            c["edges"][0]["capacity"] = 1025
        return c
    M("edge cap 1025", edge_cap_big)
    def edge_self(c):
        if c["edges"]:
            c["edges"][0]["head"] = c["edges"][0]["tail"]
        return c
    M("edge self loop", edge_self)
    def edge_node_oor(c):
        if c["edges"]:
            c["edges"][0]["head"] = c["node_count"]
        return c
    M("edge node oor", edge_node_oor)
    def com_drop(c):
        if c["commodities"]:
            c["commodities"][0].pop("previous")
        return c
    M("commodity drop key", com_drop)
    def com_same(c):
        if c["commodities"]:
            c["commodities"][0]["target"] = c["commodities"][0]["source"]
        return c
    M("commodity same endpoints", com_same)
    def com_dem(c):
        if c["commodities"]:
            c["commodities"][0]["demand"] = 1025
        return c
    M("demand 1025", com_dem)
    def com_demf(c):
        if c["commodities"]:
            c["commodities"][0]["demand"] = float(c["commodities"][0]["demand"])
        return c
    M("demand float", com_demf)
    def prev_short(c):
        if c["commodities"] and c["commodities"][0]["paths"]:
            c["commodities"][0]["previous"] = c["commodities"][0]["previous"][:-1]
        return c
    M("previous short", prev_short)
    def prev_sum(c):
        if c["commodities"] and c["commodities"][0]["previous"]:
            c["commodities"][0]["previous"][0] += 1
        return c
    M("previous sum 17", prev_sum)
    def prev_big(c):
        if c["commodities"] and c["commodities"][0]["previous"]:
            c["commodities"][0]["previous"][0] = 17
        return c
    M("previous weight 17", prev_big)
    def path_empty(c):
        if c["commodities"]:
            c["commodities"][0]["paths"].append([])
            c["commodities"][0]["previous"].append(0)
        return c
    M("empty path appended", path_empty)
    def path_dup(c):
        cm = c["commodities"][0] if c["commodities"] else None
        if cm and cm["paths"]:
            cm["paths"].append(list(cm["paths"][0]))
            cm["previous"] = [0] * len(cm["paths"])
            cm["previous"][0] = 16
        return c
    M("duplicate path", path_dup)
    def path_badedge(c):
        cm = c["commodities"][0] if c["commodities"] else None
        if cm and cm["paths"]:
            cm["paths"][0][0] = len(c["edges"]) + 5
        return c
    M("path edge oor", path_badedge)
    def path_break(c):
        cm = c["commodities"][0] if c["commodities"] else None
        if cm and len(cm["paths"]) > 1:
            cm["paths"][0] = list(cm["paths"][1])
        return c
    M("path swapped (maybe invalid)", path_break)
    def path_perm(c):
        cm = c["commodities"][0] if c["commodities"] else None
        if cm and cm["paths"] and len(cm["paths"][0]) > 1:
            p = cm["paths"][0]
            p[0], p[1] = p[1], p[0]
        return c
    M("path permuted (maybe invalid)", path_perm)
    def too_many_paths(c):
        cm = c["commodities"][0] if c["commodities"] else None
        if cm is None:
            return c
        base = cm["paths"][0] if cm["paths"] else None
        if base is None:
            return c
        for i in range(20):
            cm["paths"].append([ (base[0] + i) % max(1, len(c["edges"])) ])
            cm["previous"].append(0)
        return c
    M("17+ paths in one commodity", too_many_paths)
    def nan_budget(c):
        return json.dumps(c).replace('"budget":', '"budget": NaN,', 1)
    M("nan budget", nan_budget)
    return out


def run(batch):
    lines = []
    for label, text in batch:
        raw = text if isinstance(text, bytes) else text.encode()
        if b"\n" in raw:
            raw = raw.replace(b"\n", b" ")
        lines.append(raw)
    payload = b"".join(l + b"\n" for l in lines)
    p = subprocess.run([sys.executable, PLANNER], input=payload,
                       capture_output=True, timeout=600)
    assert p.returncode == 0, p.stderr.decode()[-2000:]
    out = p.stdout.decode().splitlines()
    assert len(out) == len(lines), (len(out), len(lines))
    return out, p.stderr.decode()


def main(seed=1, nbase=60):
    rng = random.Random(seed)
    bases = []
    for _ in range(nbase // 2):
        bases.append(gen.gen(rng))
    for _ in range(nbase - nbase // 2):
        bases.append(gen2.gen(rng))
    batch = []
    for obj in bases:
        batch.append(("VALID", json.dumps(obj)))
        batch.extend(mutations(rng, obj))
    out, err = run(batch)
    fails = 0
    for (label, text), line in zip(batch, out):
        mine = json.loads(line)["status"] == "invalid"
        ref = not refvalid.verdict(text.encode() if isinstance(text, str) else text)
        if mine != ref:
            fails += 1
            if fails < 12:
                print("DISAGREE(%s): planner_invalid=%s ref_invalid=%s\n   %s" %
                      (label, mine, ref, (text if isinstance(text, str) else text.decode())[:400]))
    print("fuzz: %d cases, %d disagreements" % (len(batch), fails))
    if err.strip():
        print("stderr:", err[:400])
    return fails


if __name__ == "__main__":
    sys.exit(1 if main(int(sys.argv[1]) if len(sys.argv) > 1 else 1,
                       int(sys.argv[2]) if len(sys.argv) > 2 else 60) else 0)
